// Select fields, derive values, and report execution time.
const repo = items[0].json;
const start = Date.now();

console.log('[etl] fetched repo: ' + repo.full_name);

const stars = repo.stargazers_count || 0;
const forks = repo.forks_count || 0;
const issues = repo.open_issues_count || 0;

const owner = repo.owner || {};

const row = {
  full_name: repo.full_name,
  name: repo.name,
  owner_login: owner.login,
  stars_per_fork: forks > 0 ? Math.round((stars / forks) * 100) / 100 : 0,
  has_open_issues: issues > 0,
  language: repo.language,
  created_at: repo.created_at
};

const elapsed = (Date.now() - start) / 1000;
console.log('[etl] transformed ' + repo.full_name + ' in ' + elapsed + 's');
console.log('[etl] execution time ' + elapsed + 's');

return [{ json: row }];
